// TypingClub daily report — runs entirely in this Code node.
// Verified edclub API quirks are baked in:
//  - Authorization header takes the RAW token (no "Bearer"/"Token" prefix).
//  - Never send a browser User-Agent (Cloudflare challenges spoofed UAs).
//  - typing_student_current_stats is POST-only with an EMPTY {} JSON body.
//  - student-progress is a plain GET, paginated via `next` URLs.
//  - Access tokens expire within hours → refresh first, every run.
const helpers = this.helpers;

const cfg = $('Config (edit me)').first().json;
const BASE = String(cfg.baseUrl || 'https://finalapps.edclub.com')
  .replace(/\/+$/, '')
  .replace(/\/drf\/[\d.]+$/, '');
const API = `${BASE}/drf/1.1.1`;
const TZ = cfg.timezone || 'Asia/Kolkata';
const CONCURRENCY = 3;

// Refresh token: prefer the rotated value persisted from earlier scheduled
// runs; fall back to the seed pasted in the Config node. NOTE: n8n only
// persists static data on ACTIVE (scheduled) executions, not manual test runs.
const staticData = $getWorkflowStaticData('global');
const refreshToken = staticData.rt || cfg.refreshTokenSeed;
if (!refreshToken || refreshToken.includes('PASTE')) {
  throw new Error('No refresh token — paste the edclub `rt` cookie value into the Config node');
}

// setTimeout may be absent from the sandbox too; retries then run without backoff.
const sleep = (ms) =>
  typeof setTimeout === 'function'
    ? new Promise((resolve) => setTimeout(resolve, ms))
    : Promise.resolve();
const http = (options) =>
  helpers.httpRequest({
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    ...options,
  });

// --- 1. Refresh the access token ---------------------------------------
// Verified contract: the rt travels as a cookie and the body MUST name the
// tenant domain ("finalapps" for finalapps.edclub.com) — without it the
// server answers 400 with an empty array.
// (string parsing, not `new URL` — the n8n task-runner sandbox has no URL global)
const DOMAIN = cfg.domain || BASE.replace(/^https?:\/\//, '').split('/')[0].split('.')[0];
const refreshRes = await http({
  method: 'POST',
  url: `${BASE}/auth/refresh_tokens/`,
  headers: {
    Accept: 'application/json',
    'Content-Type': 'application/json',
    Cookie: `rt=${refreshToken}`,
  },
  body: { domain: DOMAIN },
});
if (refreshRes.statusCode !== 200) {
  throw new Error(
    `edclub token refresh failed (HTTP ${refreshRes.statusCode}) — the rt cookie has likely expired. ` +
      'Sign in to the edclub portal and paste a fresh `rt` cookie into the Config node.'
  );
}
// Verified response shape: an ARRAY of account objects, e.g.
// [{ user_id, name, account, is_student, login_method, token: "<access token>" }].
// Prefer a non-student (teacher/admin) entry; fall back to any with a token.
const refreshBody = refreshRes.body || {};
const entries = (Array.isArray(refreshBody) ? refreshBody : [refreshBody]).filter(
  (entry) => entry && typeof entry === 'object'
);
const preferred = [...entries.filter((e) => e.is_student === false), ...entries];
let ACCESS = null;
for (const entry of preferred) {
  const found = ['token', 'at', 'access_token', 'access', 'auth_token']
    .map((key) => entry[key])
    .find((value) => typeof value === 'string' && value.length > 0);
  if (found) {
    ACCESS = found;
    break;
  }
}
if (!ACCESS) {
  throw new Error(
    'Refresh succeeded but no recognizable access token in the response — update the key list in this Code node.'
  );
}
// Persist the rotated rt (the server rotates it on every refresh; old
// values stay usable for a while, but always adopt the newest). Values may
// arrive percent-encoded; the browser stores them decoded.
const setCookies = [].concat(refreshRes.headers?.['set-cookie'] || []);
for (const cookie of setCookies) {
  const match = /^rt=([^;]+)/.exec(cookie);
  if (match) {
    try {
      staticData.rt = decodeURIComponent(match[1]);
    } catch (e) {
      staticData.rt = match[1];
    }
  }
}

const AUTH = { Accept: 'application/json', Authorization: ACCESS };

// --- 2. All active students (paginated) ---------------------------------
const roster = [];
let pageUrl = `${API}/students/?source=1&is_active=true&ordering=lname&unenrolled=false&limit=100&offset=0`;
while (pageUrl) {
  const res = await http({ method: 'GET', url: pageUrl, headers: AUTH });
  if (res.statusCode !== 200) throw new Error(`students fetch failed: HTTP ${res.statusCode}`);
  for (const s of res.body.results || []) {
    roster.push({
      id: s.id,
      name: [s.fname, s.lname].filter(Boolean).join(' ').trim() || `Student ${s.id}`,
      lastActivity: s.last_activity_date ?? null,
    });
  }
  pageUrl = res.body.next || null;
}

// --- 3. Per-student data: concurrency, retry, failure isolation ---------
async function withRetry(fn) {
  for (let attempt = 0; ; attempt += 1) {
    const res = await fn();
    if (res.statusCode === 200) return res.body;
    const retryable = res.statusCode === 429 || res.statusCode >= 500;
    if (!retryable || attempt >= 2) throw new Error(`HTTP ${res.statusCode}`);
    await sleep(500 * 2 ** attempt);
  }
}
const toNum = (value) => {
  if (value === null || value === undefined) return null;
  const n = Number.parseFloat(String(value).replace('%', ''));
  return Number.isNaN(n) ? null : n;
};

const students = new Array(roster.length);
const failedIds = [];
let cursor = 0;
async function worker() {
  while (cursor < roster.length) {
    const index = cursor;
    cursor += 1;
    const st = roster[index];
    const out = {
      ...st,
      stars: null,
      score: null,
      durationSeconds: null,
      progressPercent: null,
      failed: false,
    };
    try {
      const stats = await withRetry(() =>
        http({
          method: 'POST',
          url: `${API}/students/${st.id}/typing_student_current_stats/`,
          headers: { ...AUTH, 'Content-Type': 'application/json' },
          body: {},
        })
      );
      const records = [];
      let progressUrl = `${API}/students/${st.id}/student-progress/`;
      while (progressUrl) {
        const page = await withRetry(() => http({ method: 'GET', url: progressUrl, headers: AUTH }));
        if (Array.isArray(page)) {
          records.push(...page);
          break;
        }
        records.push(...(page.results || []));
        progressUrl = page.next || null;
      }
      if (records.length) {
        out.stars = 0;
        out.score = 0;
        out.durationSeconds = 0;
        for (const r of records) {
          out.stars += toNum(r.stars) ?? 0;
          out.score += toNum(r.score) ?? 0;
          out.durationSeconds += toNum(r.secs) ?? (toNum(r.msecs) ?? 0) / 1000;
        }
        out.durationSeconds = Math.round(out.durationSeconds);
        const dominant = [...records].sort((a, b) => (toNum(b.secs) ?? 0) - (toNum(a.secs) ?? 0))[0];
        out.progressPercent = toNum(dominant.progress_percent);
      }
      const statRow = Array.isArray(stats) ? (stats.find((r) => r?.subject === 1) ?? stats[0]) : null;
      if (!out.lastActivity && statRow?.last_active_date) out.lastActivity = statRow.last_active_date;
      if (out.progressPercent === null) out.progressPercent = statRow?.coverage_current ?? null;
    } catch (error) {
      out.failed = true;
      failedIds.push(st.id);
    }
    students[index] = out;
  }
}
await Promise.all(Array.from({ length: Math.min(CONCURRENCY, roster.length || 1) }, worker));

// --- 4. Build the Slack Block Kit report --------------------------------
const now = new Date();
const fmt = (d, opt) => new Intl.DateTimeFormat('en-US', { timeZone: TZ, ...opt }).format(d);
const dayStamp = (d) =>
  new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const daysBetween = (a, b) => {
  const [y1, m1, d1] = a.split('-').map(Number);
  const [y2, m2, d2] = b.split('-').map(Number);
  return Math.round((Date.UTC(y2, m2 - 1, d2) - Date.UTC(y1, m1 - 1, d1)) / 864e5);
};
function lastActive(iso) {
  if (!iso) return { label: 'Never practiced', status: 'never' };
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return { label: 'Unknown', status: 'never' };
  const diff = daysBetween(dayStamp(d), dayStamp(now));
  const time = fmt(d, { hour: 'numeric', minute: '2-digit', hour12: true });
  if (diff <= 0) return { label: time, status: 'today' };
  if (diff === 1) return { label: `Yesterday ${time}`, status: 'yesterday' };
  const sameYear = dayStamp(d).slice(0, 4) === dayStamp(now).slice(0, 4);
  return {
    label: fmt(d, { month: 'short', day: 'numeric', ...(sameYear ? {} : { year: 'numeric' }) }),
    status: 'stale',
  };
}
function formatDuration(total) {
  if (total === null || total === undefined || Number.isNaN(Number(total))) return '–';
  const all = Math.max(0, Math.floor(Number(total)));
  if (!all) return '0m';
  const h = Math.floor(all / 3600);
  const m = Math.floor((all % 3600) / 60);
  const s = all % 60;
  return [h && `${h}h`, m && `${m}m`, s && `${s}s`].filter(Boolean).join(' ');
}
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// First name only (e.g. "Hafis CP" → "Hafis"), escaped for mrkdwn.
const firstName = (name) => esc(String(name).trim().split(/\s+/)[0] || name);
const num = (v) => (v === null || v === undefined ? '–' : Number(v).toLocaleString('en-US'));
const pct = (v) => (v === null || v === undefined ? '–' : `${v}%`);
const medal = (r) =>
  r === 1 ? ':first_place_medal:' : r === 2 ? ':second_place_medal:' : r === 3 ? ':third_place_medal:' : `${r}.`;
const dot = (s) =>
  s === 'today' ? ':large_green_circle:' : s === 'yesterday' ? ':large_yellow_circle:' : ':red_circle:';
const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text } });
// Pack entries into section blocks, each kept under Slack's 3000-char limit.
function pack(entries, per, sep) {
  const out = [];
  let cur = [];
  let len = 0;
  for (const entry of entries) {
    if (cur.length >= per || len + entry.length + sep.length > 2900) {
      if (cur.length) out.push(section(cur.join(sep)));
      cur = [];
      len = 0;
    }
    cur.push(entry);
    len += entry.length + sep.length;
  }
  if (cur.length) out.push(section(cur.join(sep)));
  return out;
}
const longDate = fmt(now, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Section 1 — Last Activity (most recent first, never-practiced last).
const byActivity = [...students].sort((a, b) => {
  const ta = a.lastActivity ? Date.parse(a.lastActivity) : Number.NEGATIVE_INFINITY;
  const tb = b.lastActivity ? Date.parse(b.lastActivity) : Number.NEGATIVE_INFINITY;
  return tb - ta || a.name.localeCompare(b.name);
});
const activityLines = byActivity.map((s) => {
  const { label, status } = lastActive(s.lastActivity);
  return `${dot(status)} ${firstName(s.name)} — ${label}${s.failed ? '  :warning: _data unavailable_' : ''}`;
});
if (!activityLines.length) activityLines.push('_No active students found._');

// Section 2 — Scoreboard. No official rank field in the API → score desc,
// stars desc, name asc.
const ranked = students
  .filter((s) => !s.failed)
  .sort(
    (a, b) =>
      (b.score ?? 0) - (a.score ?? 0) || (b.stars ?? 0) - (a.stars ?? 0) || a.name.localeCompare(b.name)
  );
const boardEntries = ranked.map(
  (s, i) =>
    `${medal(i + 1)} ${firstName(s.name)}\n:star: ${num(s.stars)} stars   :trophy: ${num(s.score)}   :stopwatch: ${formatDuration(s.durationSeconds)}   :chart_with_upwards_trend: ${pct(s.progressPercent)}`
);
for (const s of students.filter((x) => x.failed))
  boardEntries.push(`:warning: ${firstName(s.name)} — data unavailable`);
if (!boardEntries.length) boardEntries.push('_No scoreboard data available._');

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Last Activity', emoji: true } },
  ...pack(activityLines, 20, '\n'),
  { type: 'header', text: { type: 'plain_text', text: 'TypingClub Scoreboard', emoji: true } },
  ...pack(boardEntries, 8, '\n\n'),
];

// --- 5. Split into Slack-sized messages (≤45 blocks each) ----------------
const fallback = `TypingClub daily report — ${longDate}`;
const chunks = [];
for (let i = 0; i < blocks.length; i += 45) chunks.push(blocks.slice(i, i + 45));
return chunks.map((chunk, i) => ({
  json: {
    text: chunks.length > 1 ? `${fallback} (${i + 1}/${chunks.length})` : fallback,
    blocks: chunk,
    failedIds,
  },
}));

for (const item of $input.all()) {
  const body = item.json;
  if (body && body.ok === false) {
    const e = body.error;
    const hint =
      (e === 'not_authed' || e === 'invalid_auth' || e === 'token_revoked' || e === 'token_expired')
        ? ' — your Slack session token/cookie is stale. Re-copy the xoxc token AND the d cookie from the browser into the "Slack browser session" credential.'
      : e === 'channel_not_found' ? ' — slackChannel must be the channel ID (C…) and you must be a member.'
      : e === 'no_permission' || e === 'missing_scope' ? ' — this session lacks permission to post here.'
      : '';
    throw new Error('Slack API error: ' + e + hint);
  }
}
return $input.all();
